using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using Extensions.Pack;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Enums")]
    [TestClass]
    public class RJIT_CR_BC_E_00001 : MsTestBase   
    {
        [TestMethod]
        public void Enums_Should_Not_Contain_Versions_This_Have_To_Be_Solved_By_Namespace()
        {
            var classNameWithVersionInfo = (from @enum in Enums
                let match = GlobalRegex.VersionRegex().Match(@enum.Name)
                where match.Success
                select new
                {
                    Error = $@"
Your enum name contains version infos, please manage this in your namespaces. Extensions are not effected by this rule.
----------------------------------------------------------------------------------------------------------------------------
FullName:     {@enum.FullQualifiedName}
----------------------------------------------------------------------------------------------------------------------------
Enum name:   {@enum.Name}
----------------------------------------------------------------------------------------------------------------------------
Matches:      {match}
----------------------------------------------------------------------------------------------------------------------------
"
                }).ToImmutableList();

            Assert.IsTrue(classNameWithVersionInfo.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_BC_E_00001

Enum names with version infos detected. Found '{classNameWithVersionInfo.Count}':{Environment.NewLine}{classNameWithVersionInfo.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
}
